effect.shader:
const int N = 9;
const float OFF[9] = float[9](-4.0,-3.0,-2.0,-1.0,0.0,1.0,2.0,3.0,4.0);
const float WT[9]  = float[9](0.028,0.070,0.133,0.196,0.228,0.196,0.133,0.070,0.028);
const vec3 LUMA = vec3(0.2126, 0.7152, 0.0722);

float sobel(sampler2D s, vec2 uv, vec2 tex) {
    float tl = dot(texture(s, uv + vec2(-tex.x,-tex.y)).rgb, LUMA);
    float t  = dot(texture(s, uv + vec2( 0.0, -tex.y)).rgb, LUMA);
    float tr = dot(texture(s, uv + vec2( tex.x,-tex.y)).rgb, LUMA);
    float l  = dot(texture(s, uv + vec2(-tex.x, 0.0 )).rgb, LUMA);
    float r  = dot(texture(s, uv + vec2( tex.x, 0.0 )).rgb, LUMA);
    float bl = dot(texture(s, uv + vec2(-tex.x, tex.y)).rgb, LUMA);
    float b  = dot(texture(s, uv + vec2( 0.0,  tex.y)).rgb, LUMA);
    float br = dot(texture(s, uv + vec2( tex.x, tex.y)).rgb, LUMA);
    float gx = -tl - 2.0*l - bl + tr + 2.0*r + br;
    float gy = -tl - 2.0*t - tr + bl + 2.0*b + br;
    return clamp(sqrt(gx*gx + gy*gy) * sens, 0.0, 1.0);
}

void main() {
    float edge = sobel(inputImg, acScreenNorm, acTexelSize);
    if (radius <= 0.0 || edge <= 0.01) {
        fragColor = (acPass == 0) ? texture(inputImg, acScreenNorm) : texture(hblur, acScreenNorm);
        return;
    }
    vec2 d = (acPass == 0) ? vec2(1.0, 0.0) : vec2(0.0, 1.0);
    vec2 passo = d * acTexelSize * (radius * edge * acEscalaDePixel);
    vec4 soma = vec4(0.0);
    float pesoTot = 0.0;
    for (int i = 0; i < N; i++) {
        vec2 u = acScreenNorm + passo * OFF[i];
        vec4 c = (acPass == 0) ? texture(inputImg, u) : texture(hblur, u);
        soma += c * WT[i];
        pesoTot += WT[i];
    }
    fragColor = soma / pesoTot;
}
